<script setup>
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
import Audiogram from './components/Audiogram.vue'
import { tone, noise, stopAudio, safeMinutes, oshaMinutes } from './engines/audio.js'
import { records, saveRecord, deleteRecord } from './db/otoDb.js'
const nav=[{icon:'◉',name:'Overview'},{icon:'⌁',name:'Audiometer'},{icon:'◎',name:'Tinnitus therapy'},{icon:'◖',name:'Speech clarifier'},{icon:'◔',name:'Noise dosimeter'},{icon:'▤',name:'Hearing vault'}]
const page=ref('Overview'), theme=ref('dark'), role=ref('Listener & patient'), modal=ref(''), mobile=ref(false), banana=ref(true), ear=ref('left'), freq=ref(1000), level=ref(25), warble=ref(false), pitch=ref(6400), noiseKind=ref('pink'), playing=ref(false), scene=ref(78), protection=ref(0), saved=ref([]), profile=ref('Healthy baseline'), micState=ref('Not connected'), micStream=ref(null)
const standard=ref('NIOSH'), storageMessage=ref(''), timerMinutes=ref(0), remaining=ref(0), editFrequency=ref(1000), threshold=ref(10)
let timerInterval, timerEnd
const frequencies=[250,500,1000,2000,4000,6000,8000]
const profiles={'Healthy baseline':[[10,10,5,5,10,10,15],[10,5,5,10,10,15,15]],'Noise-induced notch':[[10,10,10,15,48,30,20],[10,10,10,15,45,30,20]],'High-frequency slope':[[10,10,15,25,40,50,60],[10,10,15,25,45,55,65]],'Asymmetric hearing':[[30,35,40,35,45,50,55],[10,10,15,10,15,20,20]]}
const left=ref([...profiles['Healthy baseline'][0]]),right=ref([...profiles['Healthy baseline'][1]])
function setProfile(){left.value=[...profiles[profile.value][0]];right.value=[...profiles[profile.value][1]]}
const pta=a=>((a[1]+a[2]+a[3]+a[4])/4).toFixed(1)
const effective=computed(()=>Math.max(0,scene.value-Math.max(0,(protection.value-7)/2)))
const duration=computed(()=>{let n=standard.value==='NIOSH'?safeMinutes(effective.value):oshaMinutes(effective.value);return n>=60?`${(n/60).toFixed(1)} hours`:`${n.toFixed(1)} min`})
async function refreshRecords(){try{saved.value=await records();storageMessage.value=''}catch{storageMessage.value='Storage is unavailable. Your changes could not be saved.'}}
async function save(){try{saved.value=await saveRecord({type:page.value,profile:profile.value,left:[...left.value],right:[...right.value]});storageMessage.value='Profile saved on this device.'}catch{storageMessage.value='Storage is unavailable. Your profile was not saved.'}}
async function removeRecord(id){try{saved.value=await deleteRecord(id)}catch{storageMessage.value='Could not delete this record.'}}
function loadRecord(record){left.value=[...record.left];right.value=[...record.right];profile.value=record.profile in profiles?record.profile:'Custom profile';page.value='Audiometer'}
function updateThreshold(){const values=ear.value==='left'?left:right;values.value[frequencies.indexOf(editFrequency.value)]=Math.max(-10,Math.min(90,Number(threshold.value)));profile.value='Custom profile'}
function exportRecords(){const blob=new Blob([JSON.stringify(saved.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='otoshield-records.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function stopTherapy(fade=0){clearInterval(timerInterval);timerInterval=null;remaining.value=0;stopAudio(fade);playing.value=false}
async function playNoise(){if(playing.value){stopTherapy(.3);return}try{await noise(pitch.value,noiseKind.value);playing.value=true;if(timerMinutes.value){timerEnd=Date.now()+timerMinutes.value*60000;remaining.value=timerMinutes.value*60;timerInterval=setInterval(()=>{remaining.value=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if(!remaining.value)stopTherapy(3)},1000)}}catch{playing.value=false}}
function octaveCheck(value){stopTherapy();tone(value,'both',10)}
watch(page, (next, previous)=>{if(previous==='Tinnitus therapy' && next!==previous)stopTherapy(.3);if(previous==='Speech clarifier' && next!==previous)stopMic()})
onMounted(refreshRecords)
async function mic(){try{micStream.value=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});micState.value='Microphone connected'}catch(e){micState.value='Microphone unavailable or permission denied'}}
function stopMic(){micStream.value?.getTracks().forEach(t=>t.stop());micStream.value=null;micState.value='Not connected'}
onUnmounted(()=>{stopTherapy();stopMic()})
</script>
<template>
<div class="app" :class="[theme,{preview:mobile}]">
 <aside class="sidebar"><div class="brand"><div class="brand-mark">◖<i>◗</i></div><div><strong>oto<span>shield</span></strong><small>HEARING WELLNESS</small></div></div><div class="side-label">WORKSPACE</div><nav><button v-for="item in nav" :key="item.name" :class="{active:page===item.name}" @click="page=item.name"><span class="nav-icon">{{item.icon}}</span>{{item.name}}<span v-if="page===item.name" class="nav-dot">•</span></button></nav><div class="side-bottom"><div class="side-card"><span class="tiny-icon">✧</span><strong>A little care goes<br>a long way.</strong><p>Make hearing wellness a part of your everyday.</p><button @click="page='Audiometer'">Start a hearing check <span>↗</span></button></div><div class="side-status"><span class="status-dot"></span> All systems ready <span class="version">v1.0</span></div></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <b>{{page}}</b></div><div class="top-actions"><button class="icon-btn viewport" title="Toggle mobile preview" @click="mobile=!mobile">▣</button><select aria-label="Theme" v-model="theme"><option value="dark">◐ &nbsp; Obsidian</option><option value="light">Clinic frost</option><option value="sanctuary">Sanctuary</option><option value="eco">Eco glass</option></select><button class="icon-btn" title="Privileges" @click="modal='privileges'">⚙</button><button class="download" @click="modal='download'"><span>↓</span> Android app</button><div class="avatar">OS</div></div></header>
 <main>
 <template v-if="page==='Overview'"><div class="welcome-row"><div><div class="eyebrow"><span class="status-dot"></span> YOUR HEARING WELLNESS SPACE</div><h1>Listen to your world, <em>better.</em></h1><p class="subtitle">A little more awareness today. A lifetime of sound tomorrow.</p></div><div class="date-pill">✧ &nbsp; Your hearing companion</div></div>
 <section class="hero"><div class="hero-copy"><div class="hero-tag"><span>✦</span> YOUR HEARING, IN FOCUS</div><h2>Good hearing is<br><em>worth holding onto.</em></h2><p>From the music you love to the voices that matter, take a moment to care for the sounds that make life yours.</p><div class="hero-buttons"><button class="primary" @click="page='Audiometer'">Start hearing check <span>↗</span></button><button class="text-button" @click="page='Tinnitus therapy'">Explore sound therapy <span>→</span></button></div></div><div class="hero-art"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><div class="ear-art">◖<span>◗</span></div><div class="art-spark spark-one">✦</div><div class="art-spark spark-two">✧</div><div class="art-caption"><span class="status-dot"></span> MADE FOR YOUR EARS</div></div><div class="hero-number">01 / 04</div></section>
 <div class="section-heading"><div><div class="eyebrow muted">YOUR TOOLKIT</div><h3>Care for your hearing, your way.</h3></div><span>Everything you need, all in one place <b>✳</b></span></div>
 <section class="tool-grid"><button class="tool-card" @click="page='Audiometer'"><div class="tool-top"><div class="tool-icon mint">⌁</div><span>01 / 04</span></div><h4>Hearing check</h4><p>Get to know your hearing with a personalized, ear-by-ear check.</p><div class="card-link">Explore audiometer <span>↗</span></div></button><button class="tool-card" @click="page='Tinnitus therapy'"><div class="tool-top"><div class="tool-icon lilac">◎</div><span>02 / 04</span></div><h4>Tinnitus therapy</h4><p>Find a little quiet with sound tailored to your unique frequency.</p><div class="card-link">Explore sound therapy <span>↗</span></div></button><button class="tool-card" @click="page='Speech clarifier'"><div class="tool-top"><div class="tool-icon peach">◖</div><span>03 / 04</span></div><h4>Speech clarifier</h4><p>Bring the important sounds forward in a noisy world.</p><div class="card-link">Explore clarifier <span>↗</span></div></button><button class="tool-card" @click="page='Noise dosimeter'"><div class="tool-top"><div class="tool-icon blue">◔</div><span>04 / 04</span></div><h4>Noise dosimeter</h4><p>Keep an eye on your sound exposure, wherever life takes you.</p><div class="card-link">Explore noise levels <span>↗</span></div></button></section>
 <section class="bottom-row"><div class="insight-card"><div class="insight-icon">✳</div><div><div class="eyebrow muted">A GENTLE REMINDER</div><h4>Small habits. Sound futures.</h4><p>Give your ears a break in loud environments and keep listening levels comfortable.</p></div><button @click="page='Noise dosimeter'">Learn about sound exposure ↗</button></div><div class="privacy-card"><div class="shield">◇</div><div><h4>Your hearing, your data.</h4><p>Your saved records stay on this device.</p></div><span>↗</span></div></section>
 <div class="footnote">Designed for more mindful listening <span>✧</span> <span class="foot-right">NOT A SUBSTITUTE FOR PROFESSIONAL CARE</span></div></template>
 <template v-else><div class="module-heading"><div><div class="eyebrow"><span class="status-dot"></span> YOUR HEARING WORKSPACE</div><h1>{{page}}</h1><p class="subtitle">{{ page==='Audiometer'?'Explore your hearing, one ear at a time.':page==='Tinnitus therapy'?'Make a little space for quiet.':page==='Speech clarifier'?'Bring the sounds that matter into focus.':page==='Noise dosimeter'?'Understand your sound environment.':'Your hearing journey, saved locally.' }}</p></div><button class="outline" @click="page='Overview'">← Back to overview</button></div>
 <div class="safety">ⓘ &nbsp; {{page==='Audiometer'?'This is not a calibrated medical test. Results are illustrative and are not dB HL measurements. Consult an audiologist for diagnosis.':page==='Tinnitus therapy'?'Use a comfortable volume. Evidence for tinnitus sound therapy varies; this is not a proven treatment. Stop if discomfort occurs.':page==='Noise dosimeter'?'Simulated values are estimates. Microphones require calibration for reliable sound pressure measurements.':'This tool is for hearing wellness and is not a substitute for professional care.'}}</div>
 <template v-if="page==='Audiometer'"><div class="module-grid"><div class="panel chart-panel"><div class="panel-head"><div><div class="eyebrow muted">YOUR HEARING PROFILE</div><h3>Audiogram</h3><p>Explore example thresholds across frequencies</p></div><button class="small-toggle" @click="banana=!banana"><span :class="{on:banana}"></span> Speech banana</button></div><Audiogram :left="left" :right="right" :banana="banana"/><div class="legend"><span><i class="left-mark">×</i> Left ear</span><span><i class="right-mark">○</i> Right ear</span><span><i class="banana-mark">●</i> Speech range (illustrative)</span></div></div><div class="panel controls"><div class="eyebrow muted">HEARING CHECK</div><h3>Explore a tone</h3><p>Use headphones and start at a low, comfortable volume.</p><label>Example profile</label><select v-model="profile" @change="setProfile"><option v-for="(_,name) in profiles" :key="name">{{name}}</option><option v-if="profile==='Custom profile'">Custom profile</option></select><label>Listening ear</label><div class="segmented"><button :class="{selected:ear==='left'}" @click="ear='left'">× &nbsp; Left ear</button><button :class="{selected:ear==='right'}" @click="ear='right'">○ &nbsp; Right ear</button></div><label>Frequency <b>{{freq}} Hz</b></label><input type="range" min="250" max="16000" step="50" v-model.number="freq"><label>Relative level <b>{{level}}</b></label><input type="range" min="0" max="90" v-model.number="level"><label class="check"><input type="checkbox" v-model="warble"> Warble tone</label><button class="primary wide" @click="tone(freq,ear,level,.8,warble)">▷ &nbsp; Play tone</button><div class="edit-threshold"><label>Enter illustrative threshold</label><div class="threshold-row"><select v-model.number="editFrequency" aria-label="Threshold frequency"><option v-for="f in frequencies" :key="f" :value="f">{{f}} Hz</option></select><input v-model.number="threshold" type="number" min="-10" max="90" aria-label="Threshold value"><button class="outline" @click="updateThreshold">Set</button></div><p class="microcopy">Manual entries are not measurements. Select an ear above.</p></div><button class="outline wide" @click="save">Save profile</button><p v-if="storageMessage" class="microcopy" role="status">{{storageMessage}}</p></div></div><div class="metrics"><div class="panel"><span>LEFT EAR PROFILE PTA</span><strong>{{pta(left)}} <small>dB</small></strong><p>Average at 500 Hz–4 kHz</p></div><div class="panel"><span>RIGHT EAR PROFILE PTA</span><strong>{{pta(right)}} <small>dB</small></strong><p>Average at 500 Hz–4 kHz</p></div><div class="panel"><span>YOUR NEXT STEP</span><strong>Listen mindfully <small>✧</small></strong><p>See a professional for a calibrated test</p></div></div></template>
 <template v-else-if="page==='Tinnitus therapy'"><div class="module-grid"><div class="panel large-panel"><div class="tool-icon lilac">◎</div><div class="eyebrow muted">SOUND SANCTUARY</div><h2>Find your frequency.</h2><p>Explore gentle notched noise centered around the frequency you select. Start with your device volume low.</p><div class="frequency-display">{{pitch.toLocaleString()}} <small>Hz</small></div><input type="range" min="500" max="14000" step="50" v-model.number="pitch" :disabled="playing" aria-label="Tinnitus frequency"><div class="range-ends"><span>500 Hz</span><span>14,000 Hz</span></div><div class="button-row"><button class="outline" @click="octaveCheck(pitch/2)">▷ 0.5× octave check</button><button class="outline" @click="octaveCheck(Math.min(pitch*2,20000))">▷ 2× octave check</button></div></div><div class="panel controls"><div class="eyebrow muted">YOUR SOUND</div><h3>Notched noise</h3><p>A quiet moment, made for you.</p><label>Sound texture</label><select v-model="noiseKind" :disabled="playing"><option value="pink">Pink noise</option><option value="brown">Brown noise</option></select><label>Quick frequencies</label><div class="quick-buttons"><button :disabled="playing" @click="pitch=4100">4,100 Hz</button><button :disabled="playing" @click="pitch=6400">6,400 Hz</button><button :disabled="playing" @click="pitch=8200">8,200 Hz</button></div><label>Sleep timer</label><select v-model.number="timerMinutes" :disabled="playing"><option :value="0">No timer</option><option :value="15">15 minutes</option><option :value="30">30 minutes</option><option :value="60">60 minutes</option></select><p v-if="playing && remaining" class="microcopy">Time remaining: {{Math.floor(remaining / 60)}}:{{String(remaining % 60).padStart(2, '0')}}</p><button class="primary wide" @click="playNoise">{{playing?'Ⅱ  Stop sound':'▷  Play notched noise'}}</button><p class="microcopy">Keep the volume comfortable. Sound stops when you leave this page; the timer fades out over 3 seconds.</p></div></div></template>
 <template v-else-if="page==='Noise dosimeter'"><div class="module-grid"><div class="panel large-panel"><div class="eyebrow muted">EXPOSURE EXPLORER · SIMULATED</div><h2>Know your sound.</h2><p>Choose an environment to compare estimated NIOSH and OSHA exposure durations.</p><div class="meter"><span>{{scene}}</span><small>dBA<br>SIMULATED</small></div><input type="range" min="38" max="112" v-model.number="scene"><div class="quick-buttons"><button v-for="s in [38,78,94,103,112]" :key="s" @click="scene=s">{{s}} dBA</button></div><p class="microcopy">Library · City / café · Power tools · Concert · Jackhammer</p></div><div class="panel controls"><div class="eyebrow muted">CONSTANT LEVEL MODEL</div><h3>Exposure estimate</h3><label>Exposure standard</label><select v-model="standard"><option>NIOSH</option><option>OSHA</option></select><p class="microcopy">{{standard==='NIOSH'?'85 dBA for 8 hours · 3 dB exchange':'90 dBA for 8 hours · 5 dB exchange'}}</p><label>Hearing protection</label><select v-model.number="protection"><option :value="0">No protection</option><option :value="32">Foam plugs · NRR 32</option><option :value="15">Musician filters · NRR 15</option><option :value="28">Over-ear muffs · NRR 28</option></select><div class="result"><span>ESTIMATED EXPOSURE TIME</span><strong>{{duration}}</strong><p>Effective level: {{effective.toFixed(1)}} dBA</p></div><p class="microcopy">The model extrapolates constant-level exposure; real exposure varies. This is not a guarantee of safety. Protection estimates assume proper fit.</p></div></div></template>
 <template v-else-if="page==='Speech clarifier'"><div class="panel large-panel"><div class="tool-icon peach">◖</div><div class="eyebrow muted">LISTENING ASSISTANCE</div><h2>Clarity starts here.</h2><p>Microphone access can be enabled below. Live audio processing is not yet available; no audio is recorded or transmitted.</p><button class="primary" @click="micStream?stopMic():mic()">{{micStream?'Disconnect microphone':'Enable microphone'}}</button><p class="microcopy"><span class="status-dot"></span> {{micState}}</p></div></template>
 <template v-else><div class="panel large-panel"><div class="tool-icon mint">▤</div><div class="eyebrow muted">PRIVATE BY DESIGN</div><h2>Your hearing vault.</h2><p>Example profiles saved on this device. Clearing browser data will remove them.</p><div v-if="!saved.length" class="empty">✧<br><strong>Nothing saved just yet.</strong><p>Save an example profile from the audiometer to see it here.</p><button class="outline" @click="page='Audiometer'">Explore audiometer →</button></div><p v-if="storageMessage" class="microcopy" role="status">{{storageMessage}}</p><button v-if="saved.length" class="outline" @click="exportRecords">Export JSON ↓</button><div v-for="record in saved" :key="record.id" class="record"><span>⌁</span><div><strong>{{record.profile}}</strong><p>{{new Date(record.date).toLocaleString()}}</p></div><div class="record-actions"><button class="outline" @click="loadRecord(record)">Open</button><button class="outline" @click="removeRecord(record.id)">Delete</button></div></div></div></template>
 </template>
 </main></div>
 <nav class="mobile-nav" aria-label="Main navigation"><button v-for="item in nav" :key="item.name" :class="{active:page===item.name}" :aria-label="item.name" @click="page=item.name"><span>{{item.icon}}</span><small>{{item.name==='Tinnitus therapy'?'Therapy':item.name==='Speech clarifier'?'Speech':item.name==='Noise dosimeter'?'Noise':item.name==='Hearing vault'?'Vault':item.name}}</small></button></nav>
 <div v-if="modal" class="modal-backdrop" @click.self="modal=''" ><div class="modal"><button class="close" @click="modal=''">×</button><template v-if="modal==='privileges'"><div class="eyebrow muted">YOUR WORKSPACE</div><h2>Preferences & permissions</h2><p>Choose how you experience OtoShield.</p><label>Display role</label><select v-model="role"><option>Listener & patient</option><option>Audiologist & sound engineer pro</option><option>Auditory lab director</option></select><p class="microcopy">Roles are display preferences only, not access controls.</p><div class="permission"><span>◉ &nbsp; Web audio synthesizer</span><b>Available</b></div><div class="permission"><span>◖ &nbsp; Microphone</span><b>{{micState}}</b></div><div class="permission"><span>◇ &nbsp; Data storage</span><b>Local device</b></div></template><template v-else><div class="eyebrow muted">OTO-SHIELD FOR ANDROID</div><h2>Take hearing care with you.</h2><p>The Android app is not available for download yet. No APK has been built or verified in this release.</p><div class="permission"><span>Version</span><b>Coming soon</b></div><button class="primary wide" @click="modal=''">Got it</button></template></div></div>
</div>
</template>
